// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 v1, uint256 v2) internal {
        v1 = bound(v1, 0, 1000000000000000000000000000000);
        v2 = bound(v2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v1 + v2);
        try c.Deposit{value: v1}() {} catch { return; }
        try c.Deposit{value: v2}() {} catch { return; }
        uint256 recorded;
        try c.balances(address(this)) returns (uint256 __r) { recorded = __r; } catch { return; }
        assertTrue(recorded == v1 + v2);
    }

    function testFuzz_run(uint256 v1, uint256 v2) public {
        _run(v1, v2);
    }

    receive() external payable { }
}
